# ORIGINAL: F1c's gate (R2, audit D-0370 item 5) — the setter of the flag `debug` (pl-prologflag.c set_flag_value, unify_prolog_flag_value; pl-trace.c
# debugmode, tracemode) and the flags `shared_object_extension`, `version_git`, `libswipl` (pl-prologflag.c initPrologFlags, set_libswipl; pl-version.c
# setGITVersion) against swipl 10.1.19; the rows are generated by evidence/F1C/gen_rows.py.
# allow-new-artifact: F1c oracle rows
# test/core_lang/test_debug_flag_swipl.jl — `set_prolog_flag(debug, V)` and `debugger_show_context` accepted (they were refused by name, F1b design D4): the
# values read back (true/false, on/off, 1/0), the errors of the value (the flag keeps its value), the push stack of `debug`, `create_prolog_flag` on it, the
# run loop in debug mode (the `last_call_optimisation` and `vmi_builtin` mask bits are cleared while it is on: recursion, findall, catch, `\+`, an unknown
# procedure), `'$current_prolog_flag'/5` of the flags, and the three flags the boot reads: `shared_object_extension` (so, read-only), `version_git` (read-only;
# the PREFIX 10.1.19 only: the installed oracle was built from 10.1.19-9-ge0323664, the kernel's pin is 10.1.19-1-gcbf4e189) and `libswipl` (an atom
# holding libswipl.so; the oracle's is the path of the loaded library, read-only, the kernel's the LIBPL_PATH fallback, WRITABLE: the last testset pins the
# kernel's answer). `xref` is no C flag of upstream's: the round trip rows set it first (user_flags silent) and read it back.
#   * A PROGRAM consulted by the kernel's loader, and cases `t_<id>(R)` run IN ORDER in one database, each wrapped in
#     `catch(Goal, error(E, _), R = raised(E))` and then `set_prolog_flag(debug, false), set_prolog_flag(debugger_show_context, false)`: a case that raises
#     leaves the debug mode off for the next.
#   * Every answer line is swipl's, PINNED (swipl 10.1.19, evidence/F1C/gen_rows.py, two runs byte-identical, LC_ALL=C, one process per run); with
#     `swipl` on PATH the live answers are compared with the pins too. A swipl-only answer the kernel is not made to give is written in the comment at
#     its row.
# UNVERIFIED on the kernel: gate decides (every pin is swipl's; the rows were not run on the kernel).
using Test, LogicKernel
const LK = LogicKernel

# TERM TYPES PER CHUNK: REFERENCE — the debug flag (src/os/pl-prologflag.jl set_flag_value, src/pl-trace.jl debugmode, tracemode), built on the term layer; every type in CI and at milestones
include(joinpath(@__DIR__, "..", "term_under_test.jl"))
const _DB = lk_term_type(Union{Int64, Float64, String, BigInt, Rational{BigInt}})
_dbs(x) = lk_sym(_DB, Symbol(x))

_db_codes(s::String) = "[" * join(Int.(collect(s)), ",") * "]"
"A term as the driver's `enc/1` writes it: `V<i>` by first occurrence, atoms and functors by their codes."
function _db_enc(t::_DB, seen::Vector{UInt64}=UInt64[])::String
    k = kind(t)
    if k === VAR
        i = findfirst(==(var_key(t)), seen)
        if i === nothing
            push!(seen, var_key(t))
            i = length(seen)
        end
        return "V$(i - 1)"
    elseif k === SYM
        return is_nil(t) ? "nil" : "a" * _db_codes(sym_text(t))
    elseif k === GND
        v = lk_value(t)
        v isa AbstractString && return "s" * _db_codes(String(v))
        v isa Integer && return "i$v"
        v isa Rational && return "q$(numerator(v))r$(denominator(v))"
        v isa AbstractFloat && return "f$(v)"
        return "?$(typeof(v))"
    end
    h = child(t, 1)
    return (is_nil(h) ? "c[]" : "c" * _db_codes(sym_text(h))) * "/$(nchildren(t) - 1)(" *
           join([_db_enc(child(t, i), seen) for i in 2:nchildren(t)], ",") * ")"
end

# the swipl side: the driver of test_at_body_swipl.jl (consult, then every answer of each t_<id>/1, `enc`oded)
const _DB_DRIVER = raw"""
enc(T) :- enc(T, [], _).
enc(V, S0, S) :- var(V), !, ( vidx(S0, V, 0, I) -> S = S0 ; length(S0, I), append(S0, [V], S) ), format("V~w", [I]).
enc(T, S, S) :- T == [], !, write(nil).
enc(T, S, S) :- atom(T), !, atom_codes(T, Cs), format("a~w", [Cs]).
enc(T, S, S) :- string(T), !, string_codes(T, Cs), format("s~w", [Cs]).
enc(T, S, S) :- integer(T), !, format("i~w", [T]).
enc(T, S, S) :- rational(T, N, D), !, format("q~wr~w", [N, D]).
enc(T, S, S) :- float(T), !, format("f~w", [T]).
enc(T, S0, S) :- compound_name_arity(T, N, A),
    ( N == [] -> write('c[]') ; atom_codes(N, Cs), format("c~w", [Cs]) ),
    format("/~w(", [A]), encargs(1, A, T, S0, S), write(')').
encargs(I, A, _, S, S) :- I > A, !.
encargs(I, A, T, S0, S) :- arg(I, T, X), enc(X, S0, S1), ( I < A -> write(',') ; true ),
    I1 is I+1, encargs(I1, A, T, S1, S).
vidx([X|_], V, I, I) :- X == V, !.
vidx([_|Xs], V, I0, I) :- I1 is I0+1, vidx(Xs, V, I1, I).
fz_pred(N) :-
    format("~w", [N]), functor(G, N, 1),
    catch(findnsols(50, G, G, Gs), _, Gs = [exception]),
    forall(member(S, Gs), ( S == exception -> write(' exception') ; write(' '), enc(S) )), nl.
fz_run(File, Ns) :-
    catch(( consult(File), S = ok ), E, S = exc(E)),
    ( S == ok -> writeln(ok) ; S = exc(B), write('exc '), enc(B), nl ),
    forall(member(N, Ns), fz_pred(N)).
"""
function _db_swipl_lines(path::String, names::Vector{String})::Vector{String}
    out = mktempdir() do d
        f = joinpath(d, "drv.pl")
        write(
            f,
            _DB_DRIVER * ":- initialization((fz_run('$path', [" * join(names, ",") *
            "]), halt)).\n"
        )
        read(pipeline(`swipl -q $f`; stdin=devnull, stderr=devnull), String)
    end
    return String.(split(chomp(out), '\n'; keepempty=false))
end

