cnt(N) :- N1 is N-1, cnt(N1).
dbl(0, 0) :- !.
dbl(N, M) :- N1 is N-1, dbl(N1, M1), M is M1+2.
member(X, [X|_]).
member(X, [_|T]) :- member(X, T).
memberchk(X, L) :- member(X, L), !.
"""

