"The program and cases as one file; the case predicates' names."
function _db_file()::Tuple{String, Vector{String}}
    names = ["t_$(id)" for (id, _) in _DB_CASES]
    text =
        _DB_PROGRAM * join([
            "t_$(id)(R) :- catch(($g), error(SfE, _), R = raised(SfE)), set_prolog_flag(debug, false), set_prolog_flag(debugger_show_context, false).\n"
            for
            (id, g) in _DB_CASES
        ])
    f = joinpath(mktempdir(), "debugflag.pl")
    write(f, text)
    return f, names
end

"The kernel's answers to the query `name(R)` in `gd`: the encoded lines, at most 50 answers; a Julia exception propagates."
function _db_query(gd, ld, name::String)::String
    proc = LK.isCurrentProcedure(sym_key(_dbs(name)), 1, LK.MODULE_user(gd))
    if proc === nothing || !LK.isDefinedProcedure(gd, proc)
        return "$name undefined"
    end
    sols = String[]
    fid = LK.PL_open_foreign_frame(ld)
    a = LK.PL_new_term_refs(ld, 1)
    LK.putSlotValue!(ld, a + 1, mk_var(_DB, LK.fresh_var_keys!(1)), LK.PutVarMap())
    qid = LK.PL_open_query(
        gd, ld, nothing, LK.PL_Q_CATCH_EXCEPTION | LK.PL_Q_EXT_STATUS, proc, a
    )
    n = 0
    try
        while (n += 1) <= 50
            rc = LK.PL_next_solution(gd, ld, qid)
            if rc == LK.PL_S_TRUE || rc == LK.PL_S_LAST
                push!(
                    sols,
                    _db_enc(mk_expr(_DB, _DB[_dbs(name), lk_answers(ld, (a:a)...)...]))
                )
                rc == LK.PL_S_LAST && break
            elseif rc == LK.PL_S_EXCEPTION
                push!(sols, "exception")
                break
            else
                break
            end
        end
    finally
        LK.PL_close_query(ld, qid)
        LK.PL_close_foreign_frame(ld, fid)
    end
    return "$name" * join(" " .* sols)
end

"The kernel's lines for `names` after consulting `path`, as the driver writes swipl's; the database and the local data."
function _db_kernel(path::String, names::Vector{String})
    gd = LK.PL_global_data{_DB}()
    ld = LK.PL_local_data{_DB}(gd)
    st, ball = LK.load_file!(gd, ld, path)
    out = [st === :ok ? "ok" : "exc " * _db_enc(ball::_DB)]
    for name in names
        push!(out, _db_query(gd, ld, name))
    end
    return out, gd, ld
end

@testset "the flag debug, debugger_show_context and the three build flags as swipl's (db01-db35)" begin
    f, names = _db_file()
    kl, _, _ = _db_kernel(f, names)
    @test length(kl) == length(_DB_PINNED)
    for (k, p) in zip(kl, _DB_PINNED)
        k == p || println(stderr, "  ours  ", k, "\n  swipl ", p)
        @test k == p
    end
    # not vacuous: the pins hold both kinds of answer — a raised error and a value read back — and the debug mode itself
    raised = "c[114,97,105,115,101,100]"                 # raised(…)
    @test count(l -> occursin(raised, l), _DB_PINNED) >= 5
    @test count(l -> !occursin(raised, l) && startswith(l, "t_"), _DB_PINNED) >= 25
    # db02 reads the flag as true while it is on, then false: [true,false]
    true_false = "c[91,124,93]/2(a[116,114,117,101],c[91,124,93]/2(a[102,97,108,115,101],nil))"
    @test any(l -> startswith(l, "t_db02 ") && occursin(true_false, l), _DB_PINNED)
    @test any(l -> startswith(l, "t_db24 ") && occursin("i600", l), _DB_PINNED)    # dbl(300, M) in debug mode: M = 600
end

@testset "the pins are swipl's (live, when swipl is on PATH)" begin
    swipl = get(ENV, "LOGICKERNEL_NO_SWIPL", "") == "1" ? nothing : Sys.which("swipl")
    # the pinned table is the driver's whole output (the inert-testset guard: an assertion either way)
    @test length(_DB_PINNED) == length(_DB_CASES) + 1
    if swipl === nothing
        @info "F1C LIVE CHECK NOT RUN: `swipl` is not on PATH here. It runs in tools/run_tests.sh and CI."
    else
        f, names = _db_file()
        @test _db_swipl_lines(f, names) == _DB_PINNED
    end
end

"The encoding (`_db_enc`) of a list of atoms, as the driver writes it."
_db_atom_list_enc(xs::Vector{String})::String =
    if isempty(xs)
        "nil"
    else
        "c[91,124,93]/2(a" * _db_codes(first(xs)) * "," * _db_atom_list_enc(xs[2:end]) * ")"
    end

# THE KERNEL'S OWN ANSWERS (white-box; swipl cannot be asked for its engine's fields, and its libswipl is a different file):
#   * the local data's debugger status and the mask bits (`debugmode`, pl-trace.c:2223-2275): while `debug` is on `debugstatus.debugging` is set,
#     `PLFLAG_LASTCALL` and `PLFLAG_VMI_BUILTIN` (RUN_MODE_NORMAL) are cleared in the mask and `skiplevel` is SKIP_VERY_DEEP; off sets the bits again
#     (the flag's table value `last_call_optimisation` is NOT changed: row db09);
#   * the `silent` messages `debug_mode(true)` / `debug_mode(false)`, one per change (kept in `ld.messages`, printMessage; none for a repeated set);
#   * the access of `libswipl`: swipl 10.1.19's is `read` (set_libswipl found the library by dladdr, FF_READONLY, pl-prologflag.c:2483-2488); the kernel loads
#     no library, so the LIBPL_PATH fallback (:2491-2493) answers: an atom flag, WRITABLE: `write`. A KNOWN DIFFERENCE, pinned here with swipl's answer
#     (checklist: libswipl access read vs write, owner F8 with the dynamic-extension flags);
#   * `version_git` is exactly the pin's `git describe` with the V cut.
# UNVERIFIED on the kernel: gate decides.
@testset "the kernel's debugger status, messages, libswipl access and version_git (white-box)" begin
    text = raw"""
    r_on(R) :- set_prolog_flag(debug, true), R = ok.
    r_on_again(R) :- set_prolog_flag(debug, true), R = ok.
    r_off(R) :- set_prolog_flag(debug, false), R = ok.
    r_off_again(R) :- set_prolog_flag(debug, false), R = ok.
    r_ctx(R) :- set_prolog_flag(debugger_show_context, true), R = ok.
    r_lib(R) :- '$current_prolog_flag'(libswipl, _, _, A, T), R = [A, T].
    r_git(R) :- current_prolog_flag(version_git, R).
    r_lco_off(R) :- set_prolog_flag(last_call_optimisation, false), R = ok.
    r_lco_on(R) :- set_prolog_flag(last_call_optimisation, true), R = ok.
    """
    path = joinpath(mktempdir(), "kernel.pl")
    write(path, text)
    gd = LK.PL_global_data{_DB}()
    ld = LK.PL_local_data{_DB}(gd)
    st, _ = LK.load_file!(gd, ld, path)
    @test st === :ok
    msg_text(m) = _db_enc(m[2])
    debug_msgs() =
        [m for m in ld.messages if occursin(_db_codes("debug_mode"), msg_text(m))]
    @test !ld.debugstatus_debugging
    @test LK.truePrologFlag(ld, LK.PLFLAG_LASTCALL)
    @test LK.truePrologFlag(ld, LK.PLFLAG_VMI_BUILTIN)
    n0 = length(debug_msgs())
    ok = _db_enc(_dbs("ok"))
    @test _db_query(gd, ld, "r_on") == "r_on " * "c" * _db_codes("r_on") * "/1(" * ok * ")"
    @test ld.debugstatus_debugging
    @test !LK.truePrologFlag(ld, LK.PLFLAG_LASTCALL)
    @test !LK.truePrologFlag(ld, LK.PLFLAG_VMI_BUILTIN)
    @test ld.debugstatus_skiplevel == typemax(UInt)
    @test length(debug_msgs()) == n0 + 1
    @test occursin("a" * _db_codes("true"), msg_text(last(debug_msgs())))
    _db_query(gd, ld, "r_on_again")
    @test ld.debugstatus_debugging
    @test length(debug_msgs()) == n0 + 1                # no change, no message
    _db_query(gd, ld, "r_off")
    @test !ld.debugstatus_debugging
    @test LK.truePrologFlag(ld, LK.PLFLAG_LASTCALL)
    @test LK.truePrologFlag(ld, LK.PLFLAG_VMI_BUILTIN)
    @test length(debug_msgs()) == n0 + 2
    @test occursin("a" * _db_codes("false"), msg_text(last(debug_msgs())))
    _db_query(gd, ld, "r_off_again")
    @test !ld.debugstatus_debugging
    @test length(debug_msgs()) == n0 + 2
    # debugger_show_context is the field alone: no mode change, no message
    @test !ld.debugstatus_showContext
    _db_query(gd, ld, "r_ctx")
    @test ld.debugstatus_showContext
    @test !ld.debugstatus_debugging
    @test length(debug_msgs()) == n0 + 2
    # the build flags: the access of libswipl (swipl: read) and the exact version_git
    @test occursin(_db_atom_list_enc(["write", "atom"]), _db_query(gd, ld, "r_lib"))
    @test _db_query(gd, ld, "r_git") ==
        "r_git c" * _db_codes("r_git") * "/1(a" * _db_codes("10.1.19-1-gcbf4e189") * ")"
    # `debug` false while the debug mode is already off still sets the run-mode bits (pl-trace.c:2253 `else if (!doit) setPrologRunMode`; pl-incl.h
    # sets them whatever the table's `last_call_optimisation` says): clear LASTCALL by the flag, then `debug` false puts it back
    @test LK.truePrologFlag(ld, LK.PLFLAG_LASTCALL)
    _db_query(gd, ld, "r_lco_off")
    @test !LK.truePrologFlag(ld, LK.PLFLAG_LASTCALL)
    @test !ld.debugstatus_debugging
    _db_query(gd, ld, "r_off_again")
    @test LK.truePrologFlag(ld, LK.PLFLAG_LASTCALL)
    @test LK.truePrologFlag(ld, LK.PLFLAG_VMI_BUILTIN)
    _db_query(gd, ld, "r_lco_on")
    @test LK.truePrologFlag(ld, LK.PLFLAG_LASTCALL)
    @test length(debug_msgs()) == n0 + 2                # none of this changed the mode
    # `tracemode(true)` is reached by no flag path (the flag `debug` only turns tracing off): the direct calls. It switches the debug mode on too.
    trace_msgs() =
        [m for m in ld.messages if occursin(_db_codes("trace_mode"), msg_text(m))]
    t0 = length(trace_msgs())
    old = Ref(true)
    @test LK.tracemode(ld, true, old)
    @test old[] == false                                # the old trace mode
    @test ld.debugstatus_tracing
    @test ld.debugstatus_debugging
    @test ld.debugstatus_skiplevel == typemax(UInt)
    @test !LK.truePrologFlag(ld, LK.PLFLAG_LASTCALL)
    @test !LK.truePrologFlag(ld, LK.PLFLAG_VMI_BUILTIN)
    @test length(debug_msgs()) == n0 + 3                # debug_mode(true) from tracemode's debugmode
    @test occursin("a" * _db_codes("true"), msg_text(last(debug_msgs())))
    @test length(trace_msgs()) == t0 + 1
    @test occursin("a" * _db_codes("true"), msg_text(last(trace_msgs())))
    # "make sure trace works inside skip": a second call with the mode already on resets a lowered skip level, and answers the old mode
    ld.debugstatus_skiplevel = UInt(0)
    old2 = Ref(false)
    @test LK.tracemode(ld, true, nothing)
    @test ld.debugstatus_skiplevel == typemax(UInt)
    ld.debugstatus_skiplevel = UInt(0)
    @test LK.tracemode(ld, true, old2)
    @test old2[] == true
    @test ld.debugstatus_skiplevel == typemax(UInt)
    @test length(trace_msgs()) == t0 + 1                # no change, no message
    @test length(debug_msgs()) == n0 + 3
    # debugmode writes the old mode into the Ref (and leaves tracing alone): the flag `debug` false then also ends the trace mode
    old3 = Ref(false)
    @test LK.debugmode(ld, false, old3, UInt32(0))
    @test old3[] == true
    @test !ld.debugstatus_debugging
    @test ld.debugstatus_tracing
    @test LK.truePrologFlag(ld, LK.PLFLAG_LASTCALL)
    old4 = Ref(true)
    @test LK.debugmode(ld, false, old4, UInt32(0))      # already off: the old mode is false, nothing changes
    @test old4[] == false
    _db_query(gd, ld, "r_off")
    @test !ld.debugstatus_tracing
    @test !ld.debugstatus_debugging
    @test length(trace_msgs()) == t0 + 2
    @test occursin("a" * _db_codes("false"), msg_text(last(trace_msgs())))
    @test ld.debugstatus_skiplevel == typemax(UInt)     # nothing lowers it
    # switching the debug mode on resets a lowered skip level (pl-trace.c:2243 `debugstatus.skiplevel = SKIP_VERY_DEEP`), and off puts the run mode back
    ld.debugstatus_skiplevel = UInt(0)
    @test LK.debugmode(ld, true, nothing, UInt32(0))
    @test ld.debugstatus_debugging
    @test ld.debugstatus_skiplevel == typemax(UInt)
    @test !LK.truePrologFlag(ld, LK.PLFLAG_LASTCALL)
    @test LK.debugmode(ld, false, nothing, UInt32(0))
    @test !ld.debugstatus_debugging
    @test LK.truePrologFlag(ld, LK.PLFLAG_LASTCALL)
    # not vacuous: every check above could fail (the encodings are non-empty and the messages were counted)
    @test !isempty(_db_atom_list_enc(["write", "atom"]))
    @test length(debug_msgs()) >= 2
    @test length(trace_msgs()) >= 2
end
